package session

import (
	"fmt"
	"regexp"
	"slices"
	"strings"
)

// inheritGitConfig removes the exact local helper and noreply identity bundle
// generated by engine. Other clone-local settings belong to the operator.
func (r Repos) inheritGitConfig(path string) error {
	out, err := r.git(path, "config", "--local", "--list")
	if err != nil {
		return fmt.Errorf("read clone configuration: %w", err)
	}
	values := map[string][]string{}
	for _, line := range strings.Split(out, "\n") {
		key, value, ok := strings.Cut(line, "=")
		if ok {
			values[key] = append(values[key], value)
		}
	}
	helpers := values["credential.helper"]
	names, emails := values["user.name"], values["user.email"]
	if !slices.Equal(helpers, []string{"", "!gh auth git-credential"}) || len(names) != 1 || len(emails) != 1 {
		return nil
	}
	expected := `^[0-9]+\+` + regexp.QuoteMeta(names[0]) + `@users\.noreply\.github\.com$`
	if !regexp.MustCompile(expected).MatchString(emails[0]) {
		return nil
	}
	for _, key := range []string{"credential.helper", "user.name", "user.email"} {
		if _, err := r.git(path, "config", "--local", "--unset-all", key); err != nil {
			return fmt.Errorf("restore inherited %s: %w", key, err)
		}
	}
	return nil
}
